import{_ as a,o as e,c as o,a2 as n}from"./chunks/framework.CANn83f8.js";const s="/images/features/accounts.png",c="/images/features/account-details.png",g=JSON.parse('{"title":"Accounts","description":"","frontmatter":{},"headers":[],"relativePath":"features/accounts.md","filePath":"features/accounts.md","lastUpdated":1790713879000}'),i={name:"features/accounts.md"};function r(l,t,u,d,h,p){return e(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h1><p>ExpenseAutomator automatically detects your accounts from imported transactions.</p><p>Accounts help you understand which banks are represented in your financial activity. You do not need to create an account manually. When transactions are imported, ExpenseAutomator uses their source bank to build the Accounts list.</p><p><img src="'+s+'" alt="Accounts overview"></p><h2 id="accounts-summary" tabindex="-1">Accounts summary <a class="header-anchor" href="#accounts-summary" aria-label="Permalink to &quot;Accounts summary&quot;">​</a></h2><p>The cards at the top of the Accounts page summarize activity across all detected accounts:</p><ul><li><strong>Income:</strong> all imported money coming in</li><li><strong>Spending:</strong> all imported money going out</li><li><strong>Income left:</strong> income minus spending</li></ul><p>Income left is displayed in green when it is positive and red when spending is greater than income.</p><h2 id="accounts-list" tabindex="-1">Accounts List <a class="header-anchor" href="#accounts-list" aria-label="Permalink to &quot;Accounts List&quot;">​</a></h2><p>The Accounts list shows all banks detected from the transactions available to you.</p><p>Each row displays:</p><ul><li><strong>Account:</strong> the name of the detected bank</li><li><strong>Balance:</strong> the running balance calculated from imported transactions</li><li><strong>Income left:</strong> imported income minus imported spending</li><li><strong>Transactions:</strong> the number of transactions imported for that bank</li><li><strong>Activity:</strong> the date of the first and latest transaction recorded for the bank</li></ul><p>The activity range helps you confirm how much transaction history is available for each account.</p><p>Click the arrow on the right side of an account to open its details.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Accounts are based on imported transaction data. They are not direct connections to your bank and do not update automatically.</p></div><h2 id="account-details" tabindex="-1">Account details <a class="header-anchor" href="#account-details" aria-label="Permalink to &quot;Account details&quot;">​</a></h2><p>The account details page gives you a closer look at the activity imported for one bank.</p><p><img src="'+c+'" alt="Account details"></p><p>The heading shows the account name, total number of transactions and the available activity range. Click <strong>All accounts</strong> to return to the Accounts list.</p><h3 id="account-totals" tabindex="-1">Account totals <a class="header-anchor" href="#account-totals" aria-label="Permalink to &quot;Account totals&quot;">​</a></h3><p>The cards at the top of the page display:</p><ul><li><strong>Current balance:</strong> the running total of all imported transactions for the account</li><li><strong>Income:</strong> the total amount of imported money coming in</li><li><strong>Expenses:</strong> the total amount of imported money going out</li></ul><p>Positive balances are displayed in green. Negative balances are displayed in red.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The current balance is calculated from the transactions imported into ExpenseAutomator. It may not match your bank&#39;s current balance if the imported history is incomplete or newer transactions have not been imported.</p></div><h3 id="balance-flow" tabindex="-1">Balance flow <a class="header-anchor" href="#balance-flow" aria-label="Permalink to &quot;Balance flow&quot;">​</a></h3><p>The <strong>Balance flow</strong> chart shows how the calculated account balance changed over time.</p><p>Use the controls above the chart to select a period:</p><ul><li><strong>6M:</strong> the latest six months</li><li><strong>YTD:</strong> the current year to date</li><li><strong>1Y:</strong> the latest year</li><li><strong>2Y:</strong> the latest two years</li><li><strong>5Y:</strong> the latest five years</li><li><strong>All:</strong> all imported account history</li></ul><p>Hover over the chart to see the calculated balance on a particular date.</p><h3 id="account-transactions" tabindex="-1">Account transactions <a class="header-anchor" href="#account-transactions" aria-label="Permalink to &quot;Account transactions&quot;">​</a></h3><p>The transaction table contains the income and expenses imported for the selected account. Each row displays:</p><ul><li>The transaction date</li><li>The payee and description</li><li>The assigned category or budget</li><li>The transaction amount</li></ul><p>Positive amounts include a plus sign and are displayed in green. Use <strong>Previous</strong> and <strong>Next</strong> to move through the account&#39;s transaction history.</p>',33)])])}const f=a(i,[["render",r]]);export{g as __pageData,f as default};
